import { z } from 'zod';
import { DisplayCurrencySchema } from './enums';

/**
 * Guest checkout contracts (public /pricing flow).
 *
 * Settlement is ALWAYS USD cents — Paystack is configured for USD — while
 * `display` carries the locked conversion snapshot the visitor was shown.
 * The reference is generated by the API and handed to Paystack at
 * initialise, so one reference identifies the order everywhere.
 */

export const PlanSummarySchema = z.object({
  code: z.string().min(1),
  name: z.string().min(1),
  description: z.string().nullable(),
  unit: z.string().min(1),
  usdCents: z.number().int().positive(),
});
export type PlanSummary = z.infer<typeof PlanSummarySchema>;

export const PlansResponseSchema = z.object({ data: z.array(PlanSummarySchema) });

export const FxRateTableSchema = z.object({
  /** Local major units per 1 USD, eight-decimal strings; USD is 1.0. */
  rates: z.record(z.string()),
  fetchedAt: z.string().datetime(),
});
export const FxRatesResponseSchema = z.object({ data: FxRateTableSchema });

export const CreateOrderBodySchema = z.object({
  planCode: z.string().min(1).max(80),
  email: z.string().email(),
  /** What the visitor was shown; USD settles regardless. */
  displayCurrency: DisplayCurrencySchema.optional(),
});
export type CreateOrderBody = z.infer<typeof CreateOrderBodySchema>;

export const OrderDisplaySchema = z.object({
  currency: DisplayCurrencySchema,
  rateLocalPerUsd: z.string().min(1),
  localMinor: z.number().int().nonnegative(),
});

export const OrderSummarySchema = z.object({
  reference: z.string().min(1),
  planCode: z.string().min(1),
  status: z.enum(['pending', 'paid', 'failed', 'expired']),
  usdCents: z.number().int().positive(),
  display: OrderDisplaySchema.nullable(),
  paidAt: z.string().datetime().nullable(),
  createdAt: z.string().datetime(),
});
export type OrderSummary = z.infer<typeof OrderSummarySchema>;

export const CreateOrderResponseSchema = z.object({
  data: OrderSummarySchema.extend({
    /** Paystack hosted checkout — the only place card data ever enters. */
    authorizationUrl: z.string().url(),
  }),
});

export const VerifyOrderBodySchema = z.object({ reference: z.string().min(1).max(120) });

export const OrderStatusResponseSchema = z.object({ data: OrderSummarySchema });

export const NEXT_STEPS_AFTER_PAYMENT = [
  'A VUNVAULT engagement coordinator emails you within one business day.',
  'You receive a scoping questionnaire and two proposed kickoff slots.',
  'Work begins only after you sign the scope and rules of engagement.',
] as const;
